from math import erf, exp, log, sqrt

def Phi(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def bs_call(S, K, r, sigma, T):
    d1 = (log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return S * Phi(d1) - K * exp(-r * T) * Phi(d1 - sigma * sqrt(T))

def digital_call(S, K, r, sigma, T):
    """Price of a bet paying 1 if the share ends above K."""
    d2 = (log(S / K) + (r - sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return exp(-r * T) * Phi(d2)

def digital_put(S, K, r, sigma, T):
    """Price of a bet paying 1 if the share ends below K."""
    d2 = (log(S / K) + (r - sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return exp(-r * T) * Phi(-d2)

def spread_digital(S, K, r, sigma, T, h):
    """Call spread from K - h/2 to K + h/2, divided by h."""
    low = bs_call(S, K - h / 2, r, sigma, T)
    high = bs_call(S, K + h / 2, r, sigma, T)
    return (low - high) / h
